gin.SetMode(gin.ReleaseMode)
r := gin.Default()
srv := &Server{db: db}

api := r.Group("/api")
{
	api.POST("/auth/login", srv.login)

	authed := api.Group("")
	authed.Use(authRequired(db))
	{
		authed.GET("/me", srv.me)

		authed.GET("/meets", srv.listMeets)
		authed.GET("/events/:id", srv.eventDetail)
		authed.GET("/events/:id/live", srv.liveRanking)
		authed.GET("/events/:id/boards", srv.listBoards)
		authed.GET("/events/:id/boards/:version", srv.getBoard)

		// 赛事与项目编排：总裁判
		authed.POST("/meets", rolesRequired("chief"), srv.createMeet)
		authed.POST("/meets/:id/events", rolesRequired("chief"), srv.createEvent)
		authed.POST("/events/:id/lanes", rolesRequired("chief", "clerk"), srv.addLanes)

		// 电子计时设备（本地模拟接口）
		authed.POST("/device/readings", rolesRequired("device", "chief"), srv.uploadReading)

		// 手记与补充材料：裁判、录入员、总裁判均可（只作证据，不改名次）
		authed.POST("/lanes/:id/manual", rolesRequired("judge", "clerk", "chief"), srv.addManual)

		// 立案 / 补充依据：裁判与总裁判可立案；补充材料三类岗位都可以
		authed.POST("/events/:id/cases", rolesRequired("judge", "chief"), srv.openCase)
		authed.POST("/cases/:id/append", rolesRequired("judge", "clerk", "chief"), srv.appendCase)

		// 裁定与发布：仅总裁判
		authed.POST("/cases/:id/decision", rolesRequired("chief"), srv.decideCase)
		authed.POST("/cases/:id/reopen", rolesRequired("chief"), srv.reopenCase)
		authed.POST("/events/:id/publish", rolesRequired("chief"), srv.publish)
	}
}

// 生产模式：若前端已构建，则由 Go 一并托管静态文件
if _, err := os.Stat("frontend/dist"); err == nil {
