:root {
  --bg: #0b1622;
  --panel: #122331;
  --panel-2: #173040;
  --line: #24475a;
  --text: #e6f1f6;
  --muted: #8fb3c2;
  --accent: #22d3ee;
  --accent-2: #0e7490;
  --ok: #34d399;
  --warn: #fbbf24;
  --bad: #f87171;
  --tie: #c084fc;
  --radius: 10px;
}

* { box-sizing: border-box; }
html, body, #app { height: 100%; margin: 0; }
body {
  font-family: "PingFang SC", "Microsoft YaHei", system-ui, -apple-system, sans-serif;
  background: radial-gradient(1200px 600px at 70% -10%, #123245 0%, var(--bg) 55%);
  color: var(--text);
  font-size: 14px;
}

button {
  font: inherit;
  border: 1px solid var(--line);
  background: var(--panel-2);
  color: var(--text);
  padding: 7px 14px;
  border-radius: 8px;
  cursor: pointer;
  transition: all .15s;
}
button:hover:not(:disabled) { border-color: var(--accent); color: var(--accent); }
button:disabled { opacity: .45; cursor: not-allowed; }
button.primary { background: linear-gradient(135deg, #0891b2, #06b6d4); border-color: #06b6d4; color: #04222b; font-weight: 600; }
button.primary:hover:not(:disabled) { color: #fff; filter: brightness(1.1); }
button.danger { border-color: var(--bad); color: var(--bad); }
button.ghost { background: transparent; }
button.sm { padding: 3px 9px; font-size: 12px; }

input, select, textarea {
  font: inherit;
  background: #0c1d29;
  border: 1px solid var(--line);
  color: var(--text);
  border-radius: 8px;
  padding: 8px 10px;
  width: 100%;
}
input:focus, select:focus, textarea:focus { outline: none; border-color: var(--accent); }
label { color: var(--muted); font-size: 12px; display: block; margin-bottom: 4px; }

.row { display: flex; gap: 12px; align-items: center; }
.wrap { flex-wrap: wrap; }
.grow { flex: 1; }
.muted { color: var(--muted); }
.small { font-size: 12px; }

.tag {
  display: inline-block;
  padding: 1px 8px;
  border-radius: 999px;
  font-size: 12px;
  border: 1px solid var(--line);
  color: var(--muted);
  white-space: nowrap;
}
.tag.chief { color: #fde68a; border-color: #a16207; background: #42200688; }
.tag.judge { color: #7dd3fc; border-color: #0369a1; background: #082f4966; }
.tag.clerk { color: #a7f3d0; border-color: #047857; background: #022c2266; }
.tag.device { color: #d8b4fe; border-color: #7e22ce; background: #3b076466; }
.tag.tie { color: var(--tie); border-color: var(--tie); background: #3b076466; }
.tag.swimoff { color: #fdba74; border-color: #c2410c; background: #43140766; }
.tag.withdrawn { color: var(--bad); border-color: var(--bad); background: #450a0a66; }
.tag.electronic { color: var(--accent); border-color: var(--accent-2); }
.tag.manual { color: #86efac; border-color: #15803d; }
.tag.open { color: var(--warn); border-color: #b45309; background: #451a0366; }
.tag.decided { color: var(--ok); border-color: #047857; background: #022c2266; }
.tag.corrected { color: #fde047; border-color: #ca8a04; background: #42200688; }

.card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px;
}

table { width: 100%; border-collapse: collapse; }
th, td { padding: 9px 10px; text-align: left; border-bottom: 1px solid var(--line); vertical-align: middle; }
th { color: var(--muted); font-weight: 500; font-size: 12px; white-space: nowrap; }
tr:last-child td { border-bottom: none; }

.tabs { display: flex; gap: 4px; margin-bottom: 14px; flex-wrap: wrap; }
.tabs button { background: transparent; border-radius: 8px 8px 0 0; border-bottom: 2px solid transparent; }
.tabs button.active { color: var(--accent); border-bottom-color: var(--accent); }

.toast {
  position: fixed; top: 18px; left: 50%; transform: translateX(-50%);
  padding: 10px 20px; border-radius: 8px; z-index: 100; max-width: 80%;
  background: var(--panel-2); border: 1px solid var(--accent-2); box-shadow: 0 8px 30px #0008;
}
.toast.bad { border-color: var(--bad); color: var(--bad); }
.toast.ok { border-color: var(--ok); color: var(--ok); }

.modal-mask {
  position: fixed; inset: 0; background: #000a; z-index: 50;
  display: flex; align-items: center; justify-content: center; padding: 20px;
}
.modal { width: 520px; max-width: 100%; max-height: 88vh; overflow: auto; }
.modal h3 { margin: 0 0 12px; }

.missed-row { background: #450a0a22; }
.mono { font-variant-numeric: tabular-nums; font-family: ui-monospace, Menlo, monospace; }

.rank-badge {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 34px; padding: 2px 8px; border-radius: 8px;
  background: var(--panel-2); border: 1px solid var(--line); font-weight: 600;
}
.rank-1 { background: linear-gradient(135deg,#f59e0b55,#facc1533); border-color: #ca8a04; }
.rank-2 { background: #e2e8f022; border-color: #94a3b8; }
.rank-3 { background: #b4530933; border-color: #b45309; }

.login-wrap { min-height: 100%; display: flex; align-items: center; justify-content: center; padding: 20px; }
.login-card { width: 420px; }
.login-hero { display:flex; align-items:center; gap:12px; margin-bottom: 6px; }
.login-hero .logo { width:44px; height:44px; }
.quick-users { display:flex; gap:8px; flex-wrap:wrap; margin-top:10px; }
.quick-users button { font-size: 12px; padding: 4px 10px; }

.layout { display: grid; grid-template-columns: 270px 1fr; height: 100%; }
.sidebar { background: #0d1d29cc; border-right: 1px solid var(--line); padding: 16px; overflow-y: auto; }
.main { padding: 22px 26px; overflow-y: auto; }
.event-item { padding: 10px 12px; border-radius: 8px; cursor: pointer; margin-bottom: 6px; border: 1px solid transparent; }
.event-item:hover { background: var(--panel-2); }
.event-item.active { background: var(--panel-2); border-color: var(--accent-2); }

.banner {
  border-left: 3px solid var(--warn); background: #451a0344;
  padding: 10px 14px; border-radius: 0 8px 8px 0; margin-bottom: 14px;
}
.banner.info { border-color: var(--accent); background: #08334466; }

.section-title { font-weight:600; margin: 18px 0 8px; display:flex; align-items:center; gap:8px; }
.kv { display:grid; grid-template-columns: 92px 1fr; gap: 4px 10px; font-size: 13px; }
.kv .k { color: var(--muted); }

@media (max-width: 900px) {
  .layout { grid-template-columns: 1fr; }
  .sidebar { border-right: none; border-bottom: 1px solid var(--line); max-height: 200px; }
}

